modelica_source:
model Baseline
  extends Modelica.Electrical.Analog.Examples.OpAmps.NonInvertingAmplifier;
end Baseline;
model FINDING00878
  extends Modelica.Electrical.Analog.Examples.OpAmps.NonInvertingAmplifier(f=0);
end FINDING00878;
model FinalFINDING00878
  extends Modelica.Electrical.Analog.Examples.OpAmps.NonInvertingAmplifier(final f=0);
end FinalFINDING00878;

mos:
setCommandLineOptions("--numProcs=1 --evaluateFinalParameters=true");
setCompiler("gcc");
setCXXCompiler("g++");
loadFile("/data/mrumoca/rumoca/target/corpus/ModelicaStandardLibrary-4.1.0/Modelica/package.mo");
loadFile("/data/mrumoca/rumoca/target/corpus/ModelicaStandardLibrary-4.1.0/ModelicaTest/package.mo");
loadFile("Cases.mo");
getErrorString();
print("AUDIT_CASE Baseline\n");
simulate(Baseline, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE FINDING00878\n");
simulate(FINDING00878, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE FinalFINDING00878\n");
simulate(FinalFINDING00878, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_OVERRIDE FINDING00878\n");
system("./Baseline -override f=0 -r=FINDING00878_override.csv");
